import { test, expect } from '@playwright/test';

test.describe('Navigation Bar Active Menu Item Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should highlight the active menu item when page loads', async ({ page }) => {
    const homeLink = page.getByRole('link', { name: /home/i });

    await expect(homeLink).toHaveClass(/active|selected|current/);
  });

  test('should update active menu item highlight when navigating to different pages', async ({ page }) => {
    const aboutLink = page.getByRole('link', { name: /about/i });
    const homeLink = page.getByRole('link', { name: /home/i });

    // Initially home should be active
    await expect(homeLink).toHaveClass(/active|selected|current/);

    // Click on About link
    await aboutLink.click();
    await page.waitForURL(/about/);

    // About should now be active
    await expect(aboutLink).toHaveClass(/active|selected|current/);

    // Home should no longer be active
    await expect(homeLink).not.toHaveClass(/active|selected|current/);
  });

  test('should maintain active state when navigating between multiple menu items', async ({ page }) => {
    const homeLink = page.getByRole('link', { name: /home/i });
    const servicesLink = page.getByRole('link', { name: /services/i });
    const contactLink = page.getByRole('link', { name: /contact/i });

    // Navigate to Services
    await servicesLink.click();
    await page.waitForURL(/services/);
    await expect(servicesLink).toHaveClass(/active|selected|current/);
    await expect(homeLink).not.toHaveClass(/active|selected|current/);

    // Navigate to Contact
    await contactLink.click();
    await page.waitForURL(/contact/);
    await expect(contactLink).toHaveClass(/active|selected|current/);
    await expect(servicesLink).not.toHaveClass(/active|selected|current/);

    // Navigate back to Home
    await homeLink.click();
    await page.waitForURL(/^http:\/\/localhost:3000\/?$/);
    await expect(homeLink).toHaveClass(/active|selected|current/);
    await expect(contactLink).not.toHaveClass(/active|selected|current/);
  });

  test('should apply correct styling to active menu item', async ({ page }) => {
    const activeMenuItem = page.getByRole('link', { name: /home/i });

    // Check for visual indicators of active state
    await expect(activeMenuItem).toHaveCSS('color', /rgb\(|#/);

    // Verify the active menu item has distinct styling
    const computedStyle = await activeMenuItem.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });

    expect(computedStyle).toBeTruthy();
  });

  test('should only have one active menu item at a time', async ({ page }) => {
    const navLinks = page.getByRole('navigation').getByRole('link');

    // Count active items
    const activeItems = await navLinks.evaluateAll((elements) => {
      return elements.filter((el) => {
        const classList = el.className;
        return /active|selected|current/.test(classList);
      }).length;
    });

    expect(activeItems).toBe(1);

    // Navigate and verify still only one active
    const aboutLink = page.getByRole('link', { name: /about/i });
    await aboutLink.click();
    await page.waitForURL(/about/);

    const activeItemsAfter = await navLinks.evaluateAll((elements) => {
      return elements.filter((el) => {
        const classList = el.className;
        return /active|selected|current/.test(classList);
      }).length;
    });

    expect(activeItemsAfter).toBe(1);
  });
});
